find.example:
kcds.core.Events.on('playerCommand', (player, command, args) => {
  if (command !== 'kick' || !args[0]) {
    return;
  }
  const [target, ...others] = kcds.players.Player.find(args[0]);
  if (!target || others.length > 0) {
    kcds.core.Chat.sendToPlayer(player, 'Name one player.');
    return;
  }
  target.kick(args.slice(1).join(' '));
});

find.exampleCs:
Events.On("playerCommand", (Player player, string command, string[] args) =>
{
    if (command != "kick" || args.Length == 0)
    {
        return;
    }
    var found = Player.Find(args[0]);
    if (found.Length != 1)
    {
        Chat.SendToPlayer(player, "Name one player.");
        return;
    }
    found[0].Kick(string.Join(" ", args.Skip(1)));
});

